import { readFile } from "fs/promises";
import { NextResponse } from "next/server";
import path from "path";

// JS-free markdown twin of /docs/api. The HTML reference is a React shell; an
// agent fetching this path gets the same content as plain markdown.
// Generated by `npm run docs:api-markdown` from public/openapi.json.
//
// Note: cannot use the Edge runtime as we need fs/path modules.
export async function GET() {
  try {
    // Deliberately NOT public/docs/api.md — a public file at the same path as
    // this route makes Next.js throw "conflicting public file and page file".
    const filePath = path.join(
      process.cwd(),
      "public",
      "docs",
      "api-markdown.md",
    );
    const content = await readFile(filePath, "utf-8");

    return new NextResponse(content, {
      status: 200,
      headers: {
        "Content-Type": "text/markdown; charset=utf-8",
        "Cache-Control": "public, max-age=3600, s-maxage=3600",
        "X-Robots-Tag": "index, follow",
        // LLM-specific headers
        "X-LLM-Friendly": "true",
        "X-AI-Indexable": "true",
        Link: '</openapi.json>; rel="service-desc"; type="application/json", </docs/api>; rel="alternate"; type="text/html"',
      },
    });
  } catch {
    return NextResponse.json(
      { error: "Documentation not found" },
      { status: 404 },
    );
  }
}
